INSERT OR IGNORE INTO inquiries (id,lead_id,data) VALUES ('q1','1','{"id":"q1","leadId":1,"source":"홈페이지 · 네이버 · Gmail","campaign":"9월 가맹 문의 · 홈페이지 문의폼 (예시)","receivedAt":"2026-09-02T04:20:00Z","raw":{"성함":"김민준","연락처":"010-0000-1001","이메일":"sample1@example.com","창업 형태":"업종 변경","창업 희망지역":"경기 수원시","문의 내용":"현재 18평 카페를 운영하고 있습니다. 업종을 변경하면 기존 주방 설비를 활용할 수 있을까요? 예상 개설 비용도 알고 싶습니다. 가족과 상의 중이고 다음 달 본사 방문이 가능합니다."},"summary":"18평 카페 운영 중으로 업종 변경 검토. 기존 주방 설비 활용 가능 여부와 예상 개설 비용 문의. 가족과 논의 중이며 다음 달 본사 방문 가능.","reviewed":false,"reviewer":null,"reviewedAt":null,"aiSample":true}');
